-- =============================================================================
-- 298_market_search_demand_seed.sql
-- Markets opportunity index: head search terms per client x country with
-- monthly volume (Ahrefs Keywords Explorer, checked 2026-10-15), from
-- docs/sessions/2026-10-15/markets/SEARCH-TERMS-DRAFT.md as confirmed by the
-- owner on 2026-10-15: RawBark core = dry dog food + dog food (kibble, not
-- BARF), Venev core = category terms, Dobias no cap on any term.
-- Idempotent: one row per client x country x term x as_of.
-- Refresh: re-run the Ahrefs check and insert rows with a new as_of; the
-- signals view (297) reads the latest as_of per term.
-- =============================================================================

MERGE `oneeighty-warehouse.ref.market_search_demand` T
USING (
  SELECT *, 'Ahrefs Keywords Explorer' AS source, DATE '2026-10-15' AS as_of
  FROM UNNEST([
